            self.unsafe_http_client.client.verbose = .headers;
        }
}

pub fn discardUnusedStreamingState(self: *NetworkTask, manager: *PackageManager) void {
        _ = bun.debugAssert((!self.streaming_committed));
        if (self.tarball_stream) |stream| {
            _ = &stream;
            _ = stream.deinit();
            self.tarball_stream = null;
        }
        if (self.streaming_extract_task) |task| {
            _ = &task;
            _ = manager.preallocated_resolve_tasks.put(task);
            self.streaming_extract_task = null;
        }
}

pub fn resetStreamingForRetry(self: *NetworkTask) void {
        _ = bun.debugAssert((!self.streaming_committed));
        if (self.tarball_stream) |stream| {
            _ = &stream;
            _ = stream.resetForRetry();
        }
        self.response = .{};
}
